    writer.writeDataPage(1, 1, BytesInput.from(BYTES1), new BinaryStatistics(), BIT_PACKED, BIT_PACKED, PLAIN);
    writer.endColumn();
    writer.addBloomFilter("a.b", expectedBloomFilter);
