        BloomFilter bloomFilter = reader.readBloomFilter(meta);
        if (bloomFilter == null) {
          return null;
        }

        cache.put(meta.getPath(), bloomFilter);
      }
      return cache.get(meta.getPath());
    } catch (IOException e) {
      logger.error("Failed to read Bloom filter data", e);
    }

    return null;
  }

